import copy
import json
import hashlib
import hmac
from typing import Dict, Any, Optional
from dataclasses import dataclass, field

# Multi-tenant network proxy configuration system
# Each tenant has isolated configuration that inherits from base defaults

SECRET_KEY = b'proxy-config-hmac-key-2024'

@dataclass
class TenantConfig:
    tenant_id: str
    settings: Dict[str, Any] = field(default_factory=dict)

class ConfigRegistry:
    """Registry managing per-tenant proxy configurations with inheritance."""

    _BASE_DEFAULTS = {
        'timeout': 30,
        'max_retries': 3,
        'allowed_methods': ['GET', 'POST'],
        'rate_limit': 100,
        'upstream': {
            'host': 'localhost',
            'port': 8080,
            'tls': True,
            'verify_cert': True
        },
        'security': {
            'require_auth': True,
            'admin_access': False,
            'bypass_acl': False
        }
    }

    def __init__(self):
        self._tenants: Dict[str, TenantConfig] = {}
        self._config_cache: Dict[str, Dict[str, Any]] = {}

    def register_tenant(self, tenant_id: str) -> None:
        if tenant_id in self._tenants:
            raise ValueError(f"Tenant {tenant_id} already registered")
        self._tenants[tenant_id] = TenantConfig(tenant_id=tenant_id)

    def _deep_merge(self, base: Dict[str, Any], overlay: Dict[str, Any]) -> Dict[str, Any]:
        """Recursively merge overlay onto base config, returning new dict."""
        result = copy.deepcopy(base)
        for key, value in overlay.items():
            if key in result and isinstance(result[key], dict) and isinstance(value, dict):
                result[key] = self._deep_merge(result[key], value)
            else:
                result[key] = copy.deepcopy(value)
        return result

    def _validate_config_key(self, key: str) -> bool:
        """Validate that config key doesn't contain injection characters."""
        forbidden = [';', '&', '|', '`', '$', '\n', '\r']
        return not any(c in key for c in forbidden)

    def apply_tenant_overlay(self, tenant_id: str, config_patch: Dict[str, Any],
                             signature: str) -> bool:
        """Apply a configuration overlay for a specific tenant.

        The patch is verified via HMAC signature before application.
        Only whitelisted top-level keys can be modified by tenants.
        """
        if tenant_id not in self._tenants:
            return False

        # Verify HMAC signature of the patch
        patch_bytes = json.dumps(config_patch, sort_keys=True).encode()
        expected_sig = hmac.new(SECRET_KEY, patch_bytes, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(signature, expected_sig):
            return False

        # Whitelist check for top-level keys
        allowed_keys = {'timeout', 'max_retries', 'allowed_methods', 'rate_limit', 'upstream'}
        for key in config_patch.keys():
            if key not in allowed_keys:
                return False
            if not self._validate_config_key(key):
                return False

        # Apply the overlay using deep merge
        self._tenants[tenant_id].settings = self._deep_merge(
            self._tenants[tenant_id].settings, config_patch
        )

        # Invalidate cache
        self._config_cache.pop(tenant_id, None)
        return True

    def get_effective_config(self, tenant_id: str) -> Optional[Dict[str, Any]]:
        """Get the effective configuration for a tenant (base + overlay)."""
        if tenant_id not in self._tenants:
            return None

        if tenant_id in self._config_cache:
            return copy.deepcopy(self._config_cache[tenant_id])

        effective = self._deep_merge(
            self._BASE_DEFAULTS,
            self._tenants[tenant_id].settings
        )
        self._config_cache[tenant_id] = effective
        return copy.deepcopy(effective)


class ProxyRouter:
    """Routes requests through the proxy based on tenant configuration."""

    def __init__(self, registry: ConfigRegistry):
        self._registry = registry

    def should_allow_request(self, tenant_id: str, method: str) -> bool:
        config = self._registry.get_effective_config(tenant_id)
        if config is None:
            return False

        if config.get('security', {}).get('require_auth') is False:
            return True  # Auth bypass if require_auth disabled

        if config.get('security', {}).get('bypass_acl') is True:
            return True  # ACL bypass

        return method in config.get('allowed_methods', [])

    def get_upstream(self, tenant_id: str) -> Optional[Dict[str, Any]]:
        config = self._registry.get_effective_config(tenant_id)
        if config is None:
            return None
        return config.get('upstream', {})

    def has_admin_access(self, tenant_id: str) -> bool:
        config = self._registry.get_effective_config(tenant_id)
        if config is None:
            return False
        return config.get('security', {}).get('admin_access', False)


def handle_config_update(registry: ConfigRegistry, request_body: bytes) -> dict:
    """HTTP handler for tenant config update endpoint."""
    try:
        payload = json.loads(request_body)
    except json.JSONDecodeError:
        return {'status': 'error', 'message': 'Invalid JSON'}

    tenant_id = payload.get('tenant_id')
    config_patch = payload.get('config', {})
    signature = payload.get('signature', '')

    if not isinstance(tenant_id, str) or not isinstance(config_patch, dict):
        return {'status': 'error', 'message': 'Invalid payload format'}

    # Additional nested key validation
    def validate_nested(obj, depth=0):
        if depth > 5:
            return False
        if isinstance(obj, dict):
            for k, v in obj.items():
                if not isinstance(k, str):
                    return False
                if not validate_nested(v, depth + 1):
                    return False
        return True

    if not validate_nested(config_patch):
        return {'status': 'error', 'message': 'Invalid config structure'}

    success = registry.apply_tenant_overlay(tenant_id, config_patch, signature)
    if success:
        return {'status': 'ok'}
    return {'status': 'error', 'message': 'Update rejected'}


def handle_bulk_config_import(registry: ConfigRegistry, tenant_id: str,
                              configs: list, admin_signature: str) -> dict:
    """Bulk import configurations - admin only endpoint.

    Accepts a list of config objects and merges them sequentially.
    Each config in the list is applied as an overlay.
    """
    # Verify admin signature covers the entire batch
    batch_bytes = json.dumps(configs, sort_keys=True).encode()
    expected_sig = hmac.new(SECRET_KEY, batch_bytes, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(admin_signature, expected_sig):
        return {'status': 'error', 'message': 'Invalid admin signature'}

    if tenant_id not in registry._tenants:
        return {'status': 'error', 'message': 'Unknown tenant'}

    # Process each config in the batch
    merged = {}
    for config_item in configs:
        if not isinstance(config_item, dict):
            continue
        # Use the registry's deep merge to accumulate
        merged = registry._deep_merge(merged, config_item)

    # Apply the final merged result - note: this bypasses the per-key whitelist
    # because bulk import is admin-authenticated
    registry._tenants[tenant_id].settings = registry._deep_merge(
        registry._tenants[tenant_id].settings, merged
    )
    registry._config_cache.pop(tenant_id, None)

    return {'status': 'ok', 'applied': len(configs)}
